import sys

def main():
    input = sys.stdin.buffer.readline

    n = int(input())
    a = list(map(int, input().split()))

    top_limit = n // 2
    top = 0

    for bottom in range(top_limit, n):
        if top < top_limit and a[top] * 2 <= a[bottom]:
            top += 1

    print(top)

if __name__ == "__main__":
